require "amf.middleware.activity.config.ActivityUpdateFlags"
require "amf.middleware.activity.config.ActivityConst"
require "amf.middleware.activity.util.ActivityUtil"

local deferred = require "amf.script.sugar.deferred"
local ActivityEventCenter = require "amf.middleware.activity.event.ActivityEventCenter"
local IconEventCenter = require "amf.feature.mainscene.module.icon.event.IconEventCenter"
local ActivityDebugLog = require "amf.middleware.activity.debug.ActivityDebugLog"
local ActivityNode

local ActivityMgr = class("ActivityMgr")

function ActivityMgr:ctor()
    self._activityMap = {}
    self._iconAutoPopHandleMap = {}
    self._tmpAutoPopupData = {}
end

-- 活动框架是否启用
function ActivityMgr:isEnabled()
    if EnvUtil:isIOS()  and MaintenanceManager:getInstance():isInReview() then
        if ActivityDebugLog then
            ActivityDebugLog:logWarning("提审期间不开放，iOS不开活动")
        end
        return
    end

    return true
end

function ActivityMgr:initialize()
    if not self:isEnabled() then
        _G.amfEC:notifyFeature(FeatureEvent.ACT_INIT_OVER, {
            isFirstEnter = true,
        })
        return
    end

    self.activityModel = require("amf.middleware.activity.model.ActivityModel"):create()
    self.actInfosModel = require("amf.middleware.activity.model.ActInfosModel"):create()

    self:registerEvents()
end

function ActivityMgr:tryInitRequire()
    if self.requireInited then return end
    self.requireInited = true
    require "amf.feature.mainscene.module.icon.view.ActivityIconButton"
    ActivityNode = require "amf.middleware.activity.node.ActivityNode"
end

function ActivityMgr:registerEvents()
    _G.amfEC:registerFeature(self)
    _G.amfEC:registerSystem(self)

    IconEventCenter:register(IconEvent.ICON_SYSTEM_READY, self.onIconSystemReady, self)
    ActivityEventCenter:register(ActivityEvent.OPEN_ACTIVITY, self.onActOpenActivity, self)
    ActivityEventCenter:register(ActivityEvent.REMOVE_ACTIVITY, self.onActRemoveActivity, self)
    ActivityEventCenter:register(ActivityEvent.REBUILD_ACTIVITY_ICON, self.onActRebuildActivityIcon, self)
    ActivityEventCenter:register(ActivityEvent.SET_ACT_INFO, self.onActSetActInfo, self)
    ActivityEventCenter:register(ActivityEvent.UPDATE_SINGLE_ACTIVITY, self.onActUpdateSingleActivity, self)
    ActivityEventCenter:register(ActivityEvent.ACTIVITY_POPUP_OVER, self.onActivityPopupOver, self)
    ActivityEventCenter:register(ActivityEvent.ACTIVITY_RESOLVE_OVER, self.onActivityResolveOver, self)
    ActivityEventCenter:register(ActivityEvent.ACTIVITY_PERIOD_CHANGE, self.onActivityPeriodChange, self)
    _G.amfEC:registerNormal(NormalEvent.USER_LOGIN, self.onUserLogin, self)
end

function ActivityMgr:reloadAll()
    self:tryInitRequire()
    if not self:isEnabled() then return end
    if _G.getTopLevelId() < 20 then return end --20级以下新用户不开活动

    ActivityDebugLog:log("ActivityMgr:reloadAll， 活动框架整体更新")
    local trace_id = PerformanceMonitor:asyncTraceBegin("Activity-UpdateConfig")
    self:updateConfig(ActivityConst.ActivityConfigName):next(function(configs)
        PerformanceMonitor:asyncTraceEnd(trace_id)
        _G.activity_root_url = self.activityModel:getRootUrl()
        self:updateActivities(configs, ActivityConst.ActivityConfigName)
    end)
end

-- TODO ZSH activity_config对不上导致node更新
function ActivityMgr:updateActivities(configs, configName)
    PerformanceMonitor:traceBegin("Activity-UpdateAll")
    local versionName = "_updateVersion" .. configName
    if not self[versionName] then
        self[versionName] = 0
    end

    self[versionName] = self[versionName] + 1

    for _, v in pairs(configs) do
        local activityNode = self._activityMap[tostring(v.actId)]
        if not activityNode then
            activityNode = ActivityNode:create(v, self[versionName], self._iconSystemReady,
                self.actInfosModel:getActInfo(v.actId), self)
            self._activityMap[tostring(v.actId)] = activityNode

            ActivityDebugLog:log(v.actId,"activityNode创建")
        else
            activityNode:update(v, self[versionName], self._iconSystemReady, self.actInfosModel:getActInfo(v.actId))
            ActivityDebugLog:log(v.actId,"activityNode更新")
        end
    end

    -- 后端没有但前端节点有，代表node已过期，释放
    for k, node in pairs(self._activityMap) do
        node:setLatestConfigVersion(self[versionName])
        if node:isInvalid() then
            ActivityDebugLog:log("活动",k,"的activityNode释放")
            local disposed, disposeError = node:dispose()
            if disposed == false then
                ActivityDebugLog:logError(
                    "活动" .. tostring(k) .. "清理失败，保留Owner重试: "
                        .. tostring(disposeError)
                )
            else
                self._activityMap[k] = nil
            end
        end
    end

    self.activityNodeCount = 0

    for k,v in pairs(self._activityMap) do
        self.activityNodeCount = self.activityNodeCount + 1
    end

    PerformanceMonitor:traceEnd()
end

function ActivityMgr:updateConfig(configName)
    ALog.log("activity", "updateConfig")
    return self.activityModel:updateConfig(configName)
end

function ActivityMgr:updateActInfos()
    local d = deferred.new()
    self:tryInitRequire()
    if not self:isEnabled() then 
        d:reject()
        return d
    end
    
    ActivityDebugLog:log("ActivityMgr:updateActInfos","活动actInfo更新调用")
    self.actInfosModel:updateInfo():next(function()
        self.hasFirstUpdateActInfo = true
        d:resolve()
    end,function()
        d:reject()
    end)

    return d
end

function ActivityMgr:tryNotifyActInfo()
    self.actInfosModel:tryNotifyActInfo()
end

function ActivityMgr:onUserLogin(event)
    self.afterUser = true
    ActivityDebugLog:setAfterUser()
    local data = event:getData()
    if not data.isOffline then
        self:updateActInfos()
        self:reloadAll()
    end
end

function ActivityMgr:onIconSystemReady()
    self._iconSystemReady = true
    self:reloadAll()
end

function ActivityMgr:onActEnterMainScene(event)
    self:tryInitRequire()
    if not self:isEnabled() then
        return
    end
    local data = event:getData()
    local firstEnter = data.firstEnter
    if not firstEnter then
        self:updateActInfos()
        self:reloadAll()
    else
        self:tryNotifyActInfo()
    end

    self._isFirstEnter = firstEnter

    if EnvUtil:isDevelopMode() then
        --添加测试按钮
        ActivityDebugLog:addButton()
    end
end

function ActivityMgr:onSystemEnterForeground(event)
    if not self.afterUser then return end
    self:tryInitRequire()
    if not self:isEnabled() then
        return
    end
    self:updateActInfos()
    self:reloadAll()

    self._isHome = true
end

--节点处理完后整体处理强弹
function ActivityMgr:onActivityResolveOver(event)
    if not self:isEnabled() then
        return
    end

    local data = event:getData()
    
    local actId = data.actId
    local configVersion = data.configVersion
    local result = data.result

    local tmpTable = self._iconAutoPopHandleMap[tostring(configVersion)]

    if not self._iconAutoPopHandleMap[tostring(configVersion)] then
        self._iconAutoPopHandleMap[tostring(configVersion)] = {}
        self._iconAutoPopHandleMap[tostring(configVersion)].countNum = 0
        tmpTable = self._iconAutoPopHandleMap[tostring(configVersion)]
    end

    --有活动重新加载完成了，重新走触发
    if tmpTable[tostring(actId)] == false and result == true then
        tmpTable[tostring(actId)] = result
        tmpTable.hadHandled = false
    end

    if tmpTable.hadHandled then
        ActivityDebugLog:log("这一批节点处理完了" .. configVersion)
        return
    end

    if not tmpTable[tostring(actId)] then
        tmpTable[tostring(actId)] = result
        tmpTable.countNum = tmpTable.countNum + 1
        ActivityDebugLog:log("actId" .. actId .. "处理完毕" .. tostring(result))
    end

    if tmpTable.countNum == self.activityNodeCount and (self._isFirstEnter or self._isHome) then
        for k,v in pairs(tmpTable) do
            if v == true then
                ActivityDebugLog:log("尝试触发强弹" .. configVersion)
                _G.amfBean("PopupNewActMgr"):handleNewIconActAutoPopup(true)
                break
            end
        end
        
        tmpTable.hadHandled = true
        _G.amfEC:notifyFeature(FeatureEvent.ACT_INIT_OVER, {
            isFirstEnter = self._isFirstEnter,
            isHome = self._isHome
        })

        self._isFirstEnter = false
        self._isHome = false
    end
end

-- 重建icon
function ActivityMgr:rebuildIcon(actId)
    if not self:isEnabled() then
        return
    end
    local activityNode = self._activityMap[tostring(actId)]
    if activityNode then
        ActivityDebugLog:logWithTraceback("重建icon" .. actId)
        return activityNode:rebuildIcon()
    end
end

--重新跑一遍单个活动
function ActivityMgr:updateSingleActivity(actId)
    if not self:isEnabled() then
        return
    end
    local activityNode = self._activityMap[tostring(actId)]
    if activityNode then
        ActivityDebugLog:logWithTraceback("重跑process" .. actId)
        activityNode:updateState()
        activityNode:processing()
    end
end

-- 打开某个活动
-- delegate
-- {
--     successCallback
--     failCallback
--     endCallback
--     userClick
--     extra
-- }
function ActivityMgr:openActivity(actId, delegate)
    if not self:isEnabled() then
        safeRunCall(delegate.failCallback)
        return
    end
    local activityNode = self._activityMap[tostring(actId)]
    if activityNode then
        activityNode:openActivity(delegate)
    else
        safeRunCall(delegate.failCallback)
        ActivityDebugLog:logWarning("没有" .. actId .. "的activityConfig，不能开启")
    end
end

-- 去掉某个活动（过期调用）
function ActivityMgr:removeActivity(actId)
    if not self:isEnabled() then
        return
    end
    self.actInfosModel:removeActInfo(actId)
    local activityNode = self._activityMap[tostring(actId)]
    if activityNode then
        ActivityDebugLog:logWithTraceback("移除活动Node" .. actId)
        activityNode:tmpUnUse()
        self:clearTmpAutoPopupData()
    end
end

-- 设置actInfo，actInfo改变会触发icon的更新
function ActivityMgr:setActInfo(actId, info)
    if not self:isEnabled() then
        return
    end
    ActivityDebugLog:logWithTraceback("修改actInfo" .. actId .. tts(info))
    self.actInfosModel:setActInfo(actId, info)
end

---------------------------------------------------对外接口-------------------------------------------------------
-- 获取单个actInfo
function ActivityMgr:getActInfo(actId)
    if not self:isEnabled() then
        return
    end

    if not self.actInfosModel then 
        return 
    end
    
    return self.actInfosModel:getActInfo(actId)
end

function ActivityMgr:getActivityParticipationTags()
    if not self.actInfosModel then
        return nil
    end
    return self.actInfosModel:getActivityParticipationTags()
end

function ActivityMgr:isActExist(actId)
    if not self:isEnabled() then
        return
    end
    local activityNode = self._activityMap[tostring(actId)]
    return activityNode and activityNode:isEnabled()
end

-- 活动本次启动是否通过了配置层 isSupport 校验。
function ActivityMgr:isActSupported(actId)
    if not self:isEnabled() then return false end
    local activityNode = self._activityMap[tostring(actId)]
    if not activityNode then
        return false
    end
    return activityNode:isConfigAndActInfoSupported()
end

function ActivityMgr:isActResLoaded(actId)
    if not self:isEnabled() then
        return
    end
    local activityNode = self._activityMap[tostring(actId)]
    return activityNode and activityNode:isResLoaded()
end

function ActivityMgr:isActReady(actId)
    if not self:isEnabled() then return false end
    local activityNode = self._activityMap[tostring(actId)]
    if not activityNode then
        return false
    end
    return activityNode:isActReady()
end

-- 下载活动所有资源
function ActivityMgr:loadActivityRes(actId)
    local d = deferred.new()
    if not self:isEnabled() then
        d:reject()
        return d
    end

    local activityNode = self._activityMap[tostring(actId)]
    if not activityNode then
        d:reject()
        return d
    end

    activityNode:loadRes():next(function()
        d:resolve()
    end,function()
        d:reject()
    end)
    
    return d
end

-- 清除强弹缓存
function ActivityMgr:clearTmpAutoPopupData()
    self._tmpAutoPopupData = {}
end

-- 配置式强弹是否已被该活动的声明式注册接管。
-- 只按 actId 判定：主面板等 checkPoint 是多活动共用的槽位，按 checkPoint 判定会误伤其它活动。
-- 拿不到强弹管理器（老包/单测环境）时按“未接管”处理，与 AutoPopupMgr:addPopupConfig 的拒绝逻辑保持一致。
function ActivityMgr:isConfigAutoPopupTakenOverByRegistration(autoPopupMgr, actId)
    if actId == nil or not autoPopupMgr then
        return false
    end

    local isTakenOver = autoPopupMgr:hasRegisteredPopupForActivity(actId) == true
    if isTakenOver then
        ActivityDebugLog:log("配置式强弹已被注册式接管，不参与候选竞争", actId)
    end
    return isTakenOver
end

-- 获取强弹数据
function ActivityMgr:getAutoPopupData(delegate)
    if not self:isEnabled() then
        return {}
    end

    local key = delegate.popStage .. "_".. (delegate.isMetaPop and "metaPop" or "noMetaPop")
    if self._tmpAutoPopupData[key] then
        return self._tmpAutoPopupData[key]
    end

    local autoPopupMgr = _G.amfBean("AutoPopupMgr")
    local ret = {}
    for k, v in pairs(self._activityMap) do
        local datas = v:getAutoPopupData(delegate)
        for _, data in ipairs(datas or {}) do
            -- 剔除必须在下面的 limitNum 截断之前：被接管的候选若先占掉唯一名额，之后会在
            -- AutoPopupMgr:addPopupConfig 被拒且没有补位，同场景其它活动已被截断出局，
            -- 最终整场不弹（7026 周末无限精力曾因此不弹）。
            if not self:isConfigAutoPopupTakenOverByRegistration(autoPopupMgr, data.actId) then
                table.insert(ret, data)
            end
        end
    end

    table.sort(ret, function(a, b)
        return a.priority < b.priority
    end)

    for i = #ret, delegate.limitNum + 1, -1 do
        ret[i] = nil
    end

    if not table.isEmpty(ret) then
        self._tmpAutoPopupData[key] = ret
    end

    -- ActivityDebugLog:logAutoPop("获取强弹数据".. key .. "数量".. #ret .. "内容" .. tts(ret))

    return ret
end

function ActivityMgr:checkHasAutoPopupByMetaId(metaId)
    if not self:isEnabled() then
        return
    end

    for k, v in pairs(self._activityMap) do
        if v:checkHasAutoPopupByMetaId(metaId) then
            return true
        end
    end
    return false
end

function ActivityMgr:checkActInfoInited()
    return self.hasFirstUpdateActInfo
end

-------------------------------------------------接事件----------------------------------------------------
function ActivityMgr:onActRemoveActivity(event)
    local data = event:getData()
    local actId = data.actId
    if not actId then
        return
    end
    self:removeActivity(actId)
end

function ActivityMgr:onActRebuildActivityIcon(event)
    local data = event:getData()
    local actId = data.actId
    if not actId then
        return
    end
    self:rebuildIcon(actId)
end

function ActivityMgr:onActUpdateSingleActivity(event)
    local data = event:getData()
    local actId = data.actId
    if not actId then
        return
    end
    self:updateSingleActivity(actId)
end

function ActivityMgr:onActOpenActivity(event)
    local data = event:getData()
    local actId = data.actId
    if not actId then
        safeRunCall(data.failCallback)
        return
    end
    self:openActivity(actId, data)
end

function ActivityMgr:onActSetActInfo(event)
    local data = event:getData()
    if not data then
        he_log_error("ActivityMgr:onActSetActInfo, data is nil " .. debug.traceback())
        return
    end
    local actId = data.actId
    if not actId then
        return
    end
    self:setActInfo(actId, data)
end

function ActivityMgr:onActivityPopupOver(event)
    local data = event:getData()
    for k,v in pairs(self._activityMap) do
        v:onActivityPopupOver(data)
    end

    self:clearTmpAutoPopupData()
end

function ActivityMgr:onActivityPeriodChange()
    self:clearTmpAutoPopupData()
end

function ActivityMgr:getActivityMap()
    return self._activityMap
end

return ActivityMgr
